using System.ComponentModel;
using Microsoft.Extensions.AI;

Console.WriteLine("Research Agent Starting...");

var topic = args.Length > 0 ? string.Join(" ", args) : "the impact of quantum computing on cryptography";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the chat client with tool support
var innerClient = new OpenAI.OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "test-key")
    .GetChatClient("gpt-4o")
    .AsIChatClient();

var chatClient = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

// Create tools
var researchTools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Run the research agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.
        Use the SearchWeb tool to find information, and the TakeNote tool to record
        important findings. Search multiple angles of the topic to build comprehensive
        understanding. When you have gathered enough information, use GetNotes to
        review your notes and provide a final summary.
        """),
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// Display collected notes
var notes = researchTools.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine("\n=== Collected Notes ===\n");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"{i + 1}. {notes[i]}");
    }
}

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a query. Returns search results as text.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching: \"{query}\"");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1");
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();

            if (string.IsNullOrWhiteSpace(content) || content.Length < 50)
            {
                return $"Search results for '{query}': No detailed results found. Try a more specific query.";
            }

            // Truncate to avoid token overload
            return content.Length > 4000 ? content[..4000] : content;
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try rephrasing the query.";
        }
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote(
        [Description("The note content to record")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note taken: \"{Truncate(note, 80)}\"");
        return $"Note recorded ({_notes.Count} total notes).";
    }

    [Description("Retrieve all notes taken so far during the research.")]
    public string GetNotes()
    {
        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public List<string> GetAllNotes() => [.. _notes];

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..(maxLength - 3)] + "...";
}

